// === Tab: leaf Function ===
function leaf(xer, yer, s, r) {
	var k= 30
	push()
	stroke('#990d08')
	noFill()
	let stemLength = s/4    //random(s / 4, s / 3)
	let stemExtra = s / 2 - stemLength
	let leafLength = s - stemLength
	let ribDiv = floor(leafLength / 8)
	translate(xer, yer - stemExtra / 2)
	rotate(r)
	//xer, yer position denotes where the stem meets the rest of the leaf

	//stem
	beginShape()
	for (let y = s / 100; y > -stemLength; y--) {
		let xV = 0
		let scaler = map(y, 0, leafLength, -PI / 2, TAU - PI / 2)
		if (y >= 0) {
			xV = map(sin(scaler), -1, 1, 0, -s / 3)
		}
		let divisor = map(y, s / 100, -stemLength, 100, 200)
		if (y > 0) {
			divisor = 100
		}
		let amount = map(y, s / 100, -stemLength, s / 8, s / 2)
		let xoff = map(noise(xer, y / divisor), 0, 1, -amount, amount)
		let samount= map(y, s/100, -stemLength, 2, s/25)
		let sWidth = map(noise(xer, y / 75), 0, 1, samount/2, samount)
		curveVertex(xoff - sWidth / 2, y)

		if (floor(y) % 3 == 0) {
			arc(xoff, y, sWidth, sWidth / 2, -PI, 0)
		}

	}
	endShape()

	beginShape()
	for (let y = s / 100; y > -stemLength; y--) {
		let xV = 0
		let scaler = map(y, s / 100, leafLength, -PI / 2, TAU - PI / 2)
		if (y >= 0) {
			xV = map(sin(scaler), -1, 1, 0, -s / 3)
		}
		let divisor = map(y, 0, -stemLength, 100, 200)
		if (y > 0) {
			divisor = 100
		}

		let amount = map(y, s / 100, -stemLength, s / 8, s / 2)
		let xoff = map(noise(xer, y / divisor), 0, 1, -amount, amount)
	let samount= map(y, s/100, -stemLength, 2, s/25)
		let sWidth = map(noise(xer, y / 75), 0, 1, samount/2, samount)
		curveVertex(xoff + sWidth / 2, y)
	}
	endShape()

fill('#f4f1de')
	//now leaf edges
	beginShape()

	for (let y = 0; y < leafLength; y++) {
		let scaler = map(y, 0, leafLength, -PI / 2, TAU - PI / 2)
		let xV = map(sin(scaler), -1, 1, 0, -s / 3)
		let xoff = map(noise(xer,y / 100), 0, 1, -s / 8, s / 8)
		curveVertex(xV + xoff, y)
		if (y % ribDiv == 0 && y > ribDiv && y < leafLength - ribDiv) {
			ramount = map(abs(leafLength / 2 - (y - ribDiv)), 0, leafLength / 2, 0, s / 8)
			let rxoff = map(noise((xer,y - ribDiv) / 100), 0, 1, -ramount, ramount)
		}
	}


	for (let y = leafLength; y > 0; y--) {
		let scaler = map(y, 0, leafLength, -PI / 2, TAU - PI / 2)
		let xV = map(sin(scaler), -1, 1, 0, s / 3)
		let xoff = map(noise(xer, y / 100), 0, 1, -s / 8, s / 8)
		curveVertex(xV + xoff, y)

		if (floor(y) % ribDiv == 0 && y > ribDiv && y < leafLength - ribDiv) {
			ramount = map(abs(leafLength / 2 - (y - ribDiv)), 0, leafLength / 2, 0, s / 8)
			let rxoff = map(noise(xer, (y - ribDiv) / 100), 0, 1, -ramount, ramount)

		}

	}

	endShape()
noFill()

	//middle vein
	beginShape()
	for (let y = 0; y < leafLength; y++) {
		let scaler = map(y, 0, leafLength, -PI / 2, TAU - PI / 2)
		//let xV= map(sin(scaler),  -1, 1, 0, s/24) 

		amount = map(abs(leafLength / 2 - y), 0, leafLength / 2, 0, s / 8)
		let xoff = map(noise(xer, y / 100), 0, 1, -amount, amount)
		curveVertex(xoff, y);		

	}
	endShape()

	//'ribs'
	for (let y = 0; y < leafLength; y++) {

		let scaler = map(y, 0, leafLength, -PI / 2, TAU - PI / 2)
		let xV = map(sin(scaler), -1, 1, 0, -s / 3)
		let xoff = map(noise(xer, y / 100), 0, 1, -s / 8, s / 8)
		//curveVertex(xV+xoff, y)


			stroke('#990d08')


		if (y % ribDiv == 0 && y > ribDiv && y < leafLength - ribDiv) {
			ramount = map(abs(leafLength / 2 - (y - ribDiv)), 0, leafLength / 2, 0, s / 8)
			let rxoff = map(noise(xer, (y - ribDiv) / 100), 0, 1, -ramount, ramount)


			let p1 = createVector(xV + xoff, y)
			let p2 = createVector(rxoff, y - ribDiv)
			beginShape()
			for (let i = 0; i <= 1; i += 0.025) {
				let ib = p5.Vector.lerp(p1, p2, i)
				let amount = map(abs(i - 0.5), 0, 0.5, -s / 10, 0)
				let xoff = map(noise(xer, ib.x / 100, ib.y / 100), 1, 0, -amount, amount)
				let yoff = map(noise(yer, ib.x / 10, ib.y / 10), 0, 1, 0, -amount/2)
				curveVertex(ib.x+ xoff, ib.y+yoff)
			}
			endShape()

			let rxV = map(sin(scaler), -1, 1, 0, s / 3)

			let rp1 = createVector(rxV + xoff, y)
			let rp2 = createVector(rxoff, y - ribDiv)
			beginShape()
			for (let i = 0; i <= 1; i += 0.025) {
				let rib = p5.Vector.lerp(rp1, rp2, i)
				let amount = map(abs(i - 0.5), 0, 0.5, -s / 10, 0)
				let xoff = map(noise(xer, rib.x / 100, rib.y / 100), 0, 1, -amount, amount)
				let yoff = map(noise(yer, rib.x / 10, rib.y / 10), 0, 1, 0, -amount/2)
				curveVertex(rib.x + xoff, rib.y+yoff)
			}


			endShape()
		}
	}


	pop()

}




// === Tab: poisson dsc ===
function poissonDiscSample() {
	var k= 30
	let s = max(width, height)
	let r = s / 6
	w = r / sqrt(2)


	cols = floor(width / w)
	rows = floor(height / w)
	for (let i = 0; i < cols * rows; i++) {
		positions[i] = undefined

	}

	var pos = createVector(random(width), random(height))
	let i = floor(pos.x / w)
	let j = floor(pos.y / w)
	positions[i + j * cols] = pos
	active.push(pos)


	let _wG_1 = 0; while ((active.length > 0) && ++_wG_1 < 20000) {
		let ranIndex = floor(random(active.length))
		var rpos = active[ranIndex]
		var found = false
		for (let n = 0; n < k; n++) {
			let sample = p5.Vector.random2D()
			let m = random(2, 2 * r)
			sample.setMag(m);
			sample.add(rpos)

			var col = floor(sample.x / w)
			var row = floor(sample.y / w)

			if (col > -1 && row > -1 && col < cols && row < rows && !positions[col + row * cols]) {

				var ok = true
				for (let i = -1; i <= 1; i++) {
					for (let j = -1; j <= 1; j++) {
						var index = (col + i) + (row + j) * cols
						let neighbor = positions[index]
						if (neighbor) {
							let d = p5.Vector.dist(sample, neighbor)
							if (d < r) {
								ok = false
							}
						}
					}
				}
				if (ok) {
					found = true
					positions[col + row * cols] = sample;
					active.push(sample)
				}
			}
		}
		if (!found) {
			active.splice(ranIndex, 1)
		}
	}

}


// === Tab: mySketch ===
//for the #wccChallenge on the theme of "Falling".
//Decided early on to try to make something that I could plot of my pen plotter (pic on the Bird's Nest discord)
//Been spending a lot of time working out an algorithm to spread items across a canvas
//in a naturalistic looking way, while still taking up most the screen and not overlapping.
//I start with a Poisson disc sample, then assign random sizes to the objects. Then I check for overlap and 
//shrink each to fit. It leaves more gaps than a normal packing method, but looks more natural.
//In this case the items do overlap a bit due to their rotations and their noise-offset shapes
//, which lends it an even more naturalistic look.


let positions=[]
let active=[]
let objects=[]
let leaves=[]

function setup() {
	createCanvas(windowHeight*0.773, windowHeight);
	background('#f4f1de');
	stroke('#990d08')
	push()
	rectMode(CENTER)
	noFill()
	strokeWeight(2)
	rect(width/2, height/2, width, height)
	pop()
	noFill()
	for(let y=-10; y<height+15; y+=3){
		beginShape()
	for(let x=50; x<width-50; x+=10){
		let xoff1=map(noise(x/10, y/200), 0, 1, -30, 30)
		let yoff=map(noise(x/200, y/200), 0, 1, -30, 30)
		curveVertex(x+xoff1, constrain(y+yoff, 0, height))
	}	
		endShape()
	}




	poissonDiscSample()
	let x=0
  let y=0
  let r
	let count=0
	for (let i = 0; i <positions.length; i++) {
		if(positions[i]){
			count++
		x = positions[i].x;
		y = positions[i].y;
		r = random(height/10, height/4)

		for (let j = objects.length-1; j >= 0; j--) {


			if (dist(x, y, objects[j].pos.x, objects[j].pos.y) <= r + objects[j].r) {
				let cr = dist(x, y, objects[j].pos.x, objects[j].pos.y) - objects[j].r

				if(cr<r){
					r=cr
				}
			}
			}



		 let pos= createVector(x, y, r)
		 leaves.push(pos)
		}
	}

	for(let l of leaves){
		let rotation= map(noise(l.x/50, l.y/50), 0, 1, -PI*0.66, PI*0.66)
	leaf(l.x, l.y, l.z, rotation)
	}
}


function mousePressed() {
//adds more leaves
setup()

}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
